            robot.pick(can["id"])
            robot.place("tray")
    robot.wave()

def task(robot):
    robot.say("What colour would you like?")
    choice = robot.listen()
    cans = robot.look()
    target_can = next((can for can in cans if can["colour"].lower() == choice.lower()), None)
    if target_can:
        robot.pick(target_can["id"])
        robot.give()
    else:
        robot.say("Sorry, we don't have any cans of that colour.")

def task(robot):
    cans = robot.look()
    red_cans = [can for can in cans if can["colour"] == "red"]
    blue_cans = [can for can in cans if can["colour"] == "blue"]

    if len(red_cans) > len(blue_cans):
        if red_cans:
            can_to_give = red_cans[0]
            robot.pick(can_to_give["id"])
            robot.give()
            robot.say("Here is a red can.")
        else:
            robot.say("No red cans available.")
    else:
        if blue_cans:
            can_to_give = blue_cans[0]
            robot.pick(can_to_give["id"])
            robot.give()
            robot.say("Here is a blue can.")
        else:
            robot.say("No blue cans available.")

def task(robot):
    cans = robot.look()
    sprite_cans = [can for can in cans if can["label"] == "Sprite"]
    if not sprite_cans:
        robot.say("I'm sorry, there are no Sprite cans.")
    else:
        closest_sprite = min(sprite_cans, key=lambda can: (can["x"]**2 + can["y"]**2))
        robot.pick(closest_sprite["id"])
        robot.give()
